		{
			title = "A Chave Anil",
			hint = "Traga de volta a chave da bolsa perdida.",
			text = [=[A bolsa estava selada por encantamento, e sua chave estava com um draco verde no templo submerso do {link:swamp-of-sorrows}Pântano das Mágoas{/link}. Quando a chave foi devolvida, Jorach abriu a bolsa. Uma luz dourada se derramou sobre ele, e seus olhos se arregalaram. O que ele viu lá dentro, não disse.]=],
		},
	},
	mentions = {
		{
			text = [=[A Mansão, {link:ravenholdt-manor}Corvoforte{/link}, o convite enviado em seu nome]=],
		},
		{ text = "Emblemas da {link:syndicate}Camarilha{/link}" },
