		{ text = "Bolsa Anil Selada" },
		{ text = "A Chave Anil" },
	},
	bonds = {
		{ id = "fahrad", name = "Fahrad", note = "seu Grão-mestre Ladino" },
		{ id = "lord-aliden-perenolde", name = "Lorde Aliden Perenolde", note = "o senhor de seus inimigos" },
	},
})

Translate("ptBR", "fahrad", {
	title = "Fahrad",
	subtitle = "Grão-mestre Ladino",
	found = "Mansão de Corvoforte",
	hint = [=[Procure o mestre ladino que escreve os convites para Corvoforte.]=],
	allegiance = "Liga dos Assassinos · Corvoforte",
	sections = {
		{
			title = "Resumo",
			text = [=[Fahrad é o Grão-mestre Ladino de {link:ravenholdt-manor}Corvoforte{/link}. É ele quem observa os jovens ladrões do mundo e decide quais deles valem o ensino. Suas cartas os encontram onde quer que estejam, seladas com a marca da mansão. Quem vem precisa primeiro sobreviver a um teste de astúcia no caminho. Fahrad recebe os sobreviventes com uma risada.]=],
		},
		{
			title = "Importância",
			text = [=[Fahrad é a porta da Liga dos Assassinos. Ninguém entra nela sem passar por suas mãos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Convida ladrões promissores a {link:ravenholdt-manor}Corvoforte{/link} e os testa no caminho.
• Compra os cofres que seus ladinos abrem em campo.]=],
		},
	},
	mentions = {
		{ text = "A Mansão, {link:ravenholdt-manor}Corvoforte{/link}" },
		{ text = "Precisa-se de Cofres de Quinquilharias" },
	},
	bonds = {
		{ id = "lord-jorach-ravenholdt", name = "Lorde Jorach Ravenholdt", note = "seu mestre" },
	},
})

Translate("ptBR", "aiden-perenolde", {
	title = "Aiden Perenolde",
	subtitle = "O Rei Traidor de Alterac",
	hint = "Conheça a história do rei que vendeu suas montanhas à Horda.",
	allegiance = "Reino de Alterac",
	aliases = { "Rei Perenolde", "Lorde Aiden Perenolde" },
	sections = {
		{
			title = "Resumo",
			text = [=[Aiden Perenolde foi o último rei de {link:alterac-mountains}Alterac{/link}. Era um homem de fala mansa e culto, dono de uma bela espada que nunca usou. Seus rivais na {link:alliance}Aliança{/link} o julgavam covarde. Ele se julgava o único rei sábio o bastante para ver que a {link:horde}Horda{/link} não podia ser vencida. Na {link:second-war}Segunda Guerra{/link}, traiu a Aliança para salvar seu próprio reino, e com isso o perdeu.]=],
		},
		{
			title = "Importância",
			text = [=[A traição de Perenolde é a razão pela qual {link:alterac-mountains}Alterac{/link} jaz em ruínas. Seus herdeiros ainda sonham com a coroa que ele perdeu, e a {link:syndicate}Camarilha{/link} que eles lideram é seu amargo legado.]=],
		},
		{
			title = "Feitos",
			text = [=[• Entrou na {link:alliance}Aliança de Lordaeron{/link} só com relutância, e duvidou dela desde o início.
• Barricou os desfiladeiros de suas montanhas, depois fez um pacto secreto com {link:orgrim-doomhammer}Orgrim Doomhammer{/link} e os abriu.
• Assassinou o mensageiro que trouxe o chamado de {link:anduin-lothar}Lothar{/link} por tropas, e escondeu o corpo em seu castelo.
• Foi deposto pelo {link:terenas-menethil}Rei Terenas{/link} e confinado em seu palácio na capital arruinada.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra quando ou como Aiden Perenolde morreu. Diz-se que no cativeiro seu juízo o abandonou. Sua família foi mantida sob vigilância, e seu filho mais velho, {link:lord-aliden-perenolde}Aliden{/link}, tentou em vão limpar o nome dela.]=],
		},
	},
	chapters = {
		{
			title = "Os Desfiladeiros Abertos",
			hint = "Descubra por que a Horda atravessou Alterac tão depressa.",
			text = [=[Quando a {link:horde}Horda{/link} chegou às montanhas, Perenolde enviou uma ave a seu Chefe Guerreiro e o encontrou à noite. Achou o {link:orcs}orc{/link} culto e honrado. Fizeram um tratado: a Horda passaria sem dano, e {link:alterac-mountains}Alterac{/link} seria poupada. Perenolde deslocou seus soldados para o norte e deixou vazios os desfiladeiros do sul. Uma travessia que deveria ter levado meses levou dois dias. Só quando {link:thoras-trollbane}Thoras Trollbane{/link}, de {link:stromgarde-keep}Stromgarde{/link}, entrou em Alterac e voltou o próprio general de Perenolde contra ele os desfiladeiros foram fechados de novo.]=],
		},
		{
			title = "A Relíquia Perdida",
			hint = "Recupere a tiara da casa real de Alterac.",
			text = [=[Quando {link:alterac-mountains}Alterac{/link} caiu, a Tiara Perenolde se perdeu. Joalheiros anões a haviam feito, e suas esmeraldas eram as mais finas que tinham. Colecionadores em {link:stormwind-city}Ventobravo{/link} ainda a desejam. Ela reapareceu enfim nas mãos de um mago {link:ogres}ogro{/link} que caça tesouros nas ruínas da mesma cidade onde o rei um dia a usou.]=],
		},
	},
	mentions = {
		{ text = "A Tiara Perenolde" },
		{ text = "Mortes Nobres, contra os nobres de sua corte caída" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lorde Aliden Perenolde", note = "seu filho mais velho" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "seu aliado secreto" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "o rei que o depôs" },
		{ id = "grel-borg-the-miser", name = "Grel'borg, o Avarento", note = "guarda a tiara de sua família" },
	},
})

