	subtitle = "Desertor da Cidade Baixa",
	found = "Campo de Internação de Lordaeron",
	hint = [=[Encontre o desertor Renegado mantido no campo perto de Dalaran.]=],
	allegiance = "Nenhuma (desertor Renegado)",
	aliases = { "Kegan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kegan Darkmar é um de quatro {link:forsaken}Renegados{/link} que deram as costas à {link:undercity}Cidade Baixa{/link}. Invadiram uma câmara segura da Dama Sombria, roubaram quatro artefatos de que seus boticários precisavam e fugiram para {link:dalaran}Dalaran{/link}. Os magos não os receberam bem. Puseram os quatro em quarentena no {link:lordamere-internment-camp}Campo de Internação de Lordaeron{/link}. Kegan e seus camaradas Ricter, Alina e Dermot esperam ali agora, entre os magos que os prendem e os Renegados que os caçam.]=],
		},
		{
			title = "Importância",
			text = [=[A fuga de Kegan mostra que nem todos os {link:forsaken}Renegados{/link} se contentam em servir à Dama Sombria.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra por que os quatro fugiram, nem o que esperavam encontrar em {link:dalaran}Dalaran{/link}.]=],
		},
	},
	mentions = {
		{ text = "Invasão à Prisão" },
	},
	bonds = {
		{ id = "warden-belamoore", name = "Guardiã Belamoore", note = "sua carcereira" },
		{ id = "magus-wordeen-voidglare", name = "Magus Wordeen Voidglare", note = "caça-o" },
	},
})

Translate("ptBR", "prospector-stonehewer", {
	title = "Prospectora Stonehewer",
	subtitle = "Exploradora da Expedição Lançatroz",
	found = "O acampamento Lançatroz fora do Vale Alterac",
	hint = [=[Fale com a prospectora anã no acampamento da Aliança fora do Vale Alterac.]=],
	allegiance = "Guarda de Lançatroz · Liga dos Exploradores",
	aliases = { "Stonehewer" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Prospectora Stonehewer serve à {link:explorers-league}Liga dos Exploradores{/link} na expedição {link:stormpike-guard}Lançatroz{/link}. A Liga acredita que o {link:alterac-valley}Vale Alterac{/link} esconde artefatos do passado, mas os {link:frostwolf-clan}orcs Lobo do Gelo{/link} não deixam os anões procurá-los. A resposta de Stonehewer é simples. Se os orcs perderem seu general, os exploradores terão espaço para escavar.]=],
		},
		{
			title = "Importância",
			text = [=[Stonehewer fala pelo lado erudito da causa {link:stormpike-guard}Lançatroz{/link}: a busca por relíquias que, dizem os anões, os atraiu ao vale.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia soldados ao vale contra {link:drek-thar}Drek'Thar{/link}.
• Honra os maiores heróis de {link:stormpike-guard}Lançatroz{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Batalha de {link:alterac-mountains}Alterac{/link}" },
		{ text = "Herói de {link:stormpike-guard}Lançatroz{/link}" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "o general que ela quer derrotado" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "seu general" },
	},
})

Translate("ptBR", "voggah-deathgrip", {
	title = "Voggah Deathgrip",
	subtitle = "Soldado do Lobo do Gelo",
	found = "O acampamento Lobo do Gelo fora do Vale Alterac",
	hint = [=[Fale com o orc que reúne guerreiros no acampamento da Horda fora do Vale Alterac.]=],
	allegiance = "Clã Lobo do Gelo · Horda",
	aliases = { "Voggah" },
	sections = {
