			title = "Feitos",
			text = [=[• Envia guerreiros ao vale contra {link:vanndar-stormpike}Vanndar Stormpike{/link}.
• Honra os maiores heróis do {link:frostwolf-clan}Lobo do Gelo{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Batalha por {link:alterac-mountains}Alterac{/link}" },
		{ text = "Herói do {link:frostwolf-clan}Lobo do Gelo{/link}" },
	},
	bonds = {
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "o general que ele quer derrotado" },
		{ id = "drek-thar", name = "Drek'Thar", note = "seu chefe" },
	},
})

Translate("ptBR", "vanndar-stormpike", {
	title = "Vanndar Stormpike",
	subtitle = "General da Guarda de Lançatroz",
	found = "Dun Baldar, no norte do Vale Alterac",
	hint = [=[Procure o general anão em sua fortaleza na ponta norte do Vale Alterac.]=],
	allegiance = "Guarda de Lançatroz · Reino de Altaforja",
	aliases = { "Vanndar" },
	sections = {
		{
			title = "Resumo",
			text = [=[Vanndar Stormpike é o general da {link:stormpike-guard}Guarda de Lançatroz{/link}, a expedição anã que entrou no {link:alterac-valley}Vale Alterac{/link}. De sua fortaleza de Dun Baldar, no norte do vale, ele comanda anões e seus aliados de todas as raças da {link:alliance}Aliança{/link}. É um senhor da montanha de poucas palavras e propósito firme. O vale, promete ele, será deles.]=],
		},
		{
			title = "Importância",
			text = [=[Vanndar é a lança de {link:kingdom-of-ironforge}Altaforja{/link} no norte. Sua expedição veio, diz-se, escavar em busca de minério e das relíquias do passado. Seu rei lhe deu uma tarefa mais dura: tomar os vales de {link:alterac-mountains}Alterac{/link} e mantê-los para {link:ironforge}Altaforja{/link}. Essa tarefa o pôs em guerra com o {link:frostwolf-clan}clã Lobo do Gelo{/link}, cujo lar é o vale desde que os Lobo do Gelo foram exilados ali.]=],
		},
		{
			title = "Feitos",
			text = [=[• Lidera a {link:stormpike-guard}Guarda de Lançatroz{/link} a partir de Dun Baldar.
• Trava guerra contra o {link:frostwolf-clan}clã Lobo do Gelo{/link} e contra os trolls Invernacha do vale.
• Recebe os soldados que a {link:alliance}Aliança{/link} envia ao vale.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco está escrito sobre Vanndar antes da expedição, ou sobre seu parentesco com outros anões que levam o nome Stormpike.]=],
		},
	},
	chapters = {
		{
			title = "O Imperativo Soberano",
			hint = "Atenda ao chamado de Altaforja aos vales de Alterac.",
			text = [=[O chamado foi feito em nome do Rei {link:magni-bronzebeard}Magni Bronzebeard{/link}. Os {link:stormpike-guard}Lançatroz{/link} lutavam contra trolls de um lado e orcs do outro, e precisavam de soldados. A tomada daquela terra, declararam os anões, era direito e dever de {link:ironforge}Altaforja{/link}. Os novos recrutas eram instruídos a procurar o Tenente Haggerdin fora do vale e começar seu serviço entre os Lançatroz.]=],
		},
		{
			title = "A Batalha por Alterac",
			hint = "Enfrente o general em Dun Baldar.",
			text = [=[Os {link:frostwolf-clan}Lobo do Gelo{/link} veem a questão de outro modo. Para eles, os {link:stormpike-guard}Lançatroz{/link} são invasores. Seus guerreiros pretendem abrir caminho para o norte através do vale até Dun Baldar e abater o general em sua própria fortaleza.]=],
		},
	},
	mentions = {
		{ text = "O Imperativo Soberano" },
		{ text = "A Batalha por {link:alterac-mountains}Alterac{/link}" },
		{ text = "Campo de Provas" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "seu inimigo" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu rei" },
		{ id = "prospector-stonehewer", name = "Prospectora Stonehewer", note = "busca relíquias para a expedição" },
	},
})

Translate("ptBR", "drek-thar", {
	title = "Drek'Thar",
	subtitle = "Xamã Ancião do Clã Lobo do Gelo",
	found = "Bastilha Lobo do Gelo, no sul do Vale Alterac",
	hint = [=[Procure o velho xamã que governa da Bastilha Lobo do Gelo, na ponta sul do Vale Alterac.]=],
	allegiance = "Clã Lobo do Gelo · Horda",
	aliases = { "Drek'thar" },
	sections = {
		{
			title = "Resumo",
			text = [=[Drek'Thar é o xamã ancião do {link:frostwolf-clan}Clã Lobo do Gelo{/link} e o general de seus guerreiros no {link:alterac-valley}Vale Alterac{/link}. É cego, e é velho. Foi xamã dos Lobo do Gelo em Draenor, e seguiu seu povo ao exílio nestas montanhas. Há muito tempo, tomou sob seus cuidados um jovem {link:orcs}orc{/link} chamado {link:thrall}Thrall{/link} e o ensinou a falar com os espíritos. Agora lidera os Lobo do Gelo de sua bastilha no sul do vale.]=],
		},
		{
			title = "Importância",
			text = [=[Drek'Thar é o mestre do Chefe Guerreiro. Por meio dele, os velhos caminhos do xamã voltaram aos orcs e, por meio de {link:thrall}Thrall{/link}, voltaram a toda a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Manteve os {link:frostwolf-clan}Lobo do Gelo{/link} vivos em seu exílio em {link:alterac-mountains}Alterac{/link}.
• Ensinou a {link:thrall}Thrall{/link} o caminho do xamã e lhe revelou quem eram seus pais.
• Lidera a defesa do {link:alterac-valley}Vale Alterac{/link} contra a {link:stormpike-guard}Guarda de Lançatroz{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Filho de Durotan",
			hint = "Descubra como o Chefe Guerreiro chegou aos Lobo do Gelo.",
			text = [=[Quando um jovem {link:orcs}orc{/link} criado por humanos chegou ao acampamento {link:frostwolf-clan}Lobo do Gelo{/link}, trazia um cobertor rasgado de sua infância. Drek'Thar conhecia suas marcas. O estranho era o filho de Durotan, o chefe que havia conduzido o clã ao exílio e que fora assassinado com sua companheira. O velho xamã pôs à prova o orgulho e a humildade do jovem orc, e depois o ensinou os caminhos dos espíritos.]=],
		},
		{
			title = "Em Defesa do Lobo do Gelo",
			hint = "Fique ao lado dos Lobo do Gelo em seu vale.",
			text = [=[Agora anões entraram no vale que abrigou os {link:frostwolf-clan}Lobo do Gelo{/link} em seus anos mais sombrios. O clã que é caro ao Chefe Guerreiro está sob ataque, e o chamado ecoou por toda a {link:horde}Horda{/link}. Guerreiros são enviados ao norte da {link:tarren-mill}Serraria Tarren{/link}, ao Mestre de Guerra Laggrond, que os testa na entrada do vale antes que lutem.]=],
		},
	},
	mentions = {
		{ text = "Em Defesa do {link:frostwolf-clan}Lobo do Gelo{/link}" },
		{ text = "A Batalha de {link:alterac-mountains}Alterac{/link}" },
		{ text = "Campo de Provas" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu discípulo e Chefe Guerreiro" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "seu inimigo" },
		{ id = "voggah-deathgrip", name = "Voggah Deathgrip", note = "envia guerreiros em seu auxílio" },
	},
})

Translate("ptBR", "crushridge-ogres", {
	title = "Ogros Esmagaterra",
	aliases = { "Esmagaterra", "ogro Esmagaterra", "clã Esmagaterra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Esmagaterra são um bando guerreiro de {link:ogres}ogros{/link} que tomou para si as ruínas da antiga capital de {link:alterac-mountains}Alterac{/link}. Brutos, espancadores, belicistas, executores e magos enchem as ruas por onde os reis de Alterac um dia cavalgaram. Cavaram um grande monte nas colinas próximas e um segundo mais fundo nas montanhas, e suas patrulhas guardam a encruzilhada rumo à {link:tarren-mill}Serraria Tarren{/link}.]=],
		},
		{
			title = "A Coroa da Vontade",
			text = [=[Os Esmagaterra não vieram a {link:alterac-mountains}Alterac{/link} por vontade própria. Seu senhor da guerra {link:mug-thol}Mug'thol{/link} estava submetido ao serviço de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, e ela enviou seu bando às montanhas para recuperar uma relíquia chamada Coroa da Vontade. Mug'thol encontrou a coroa e a pôs na cabeça. Ela o libertou do domínio da Dama Sombria, e seus ogros o seguiram às ruínas como senhores de si. Três tenentes, Targ, Muckrake e Glommus, estão a seu lado, e o mago {link:ogres}ogro{/link} {link:grel-borg-the-miser}Grel'borg{/link} vasculha a cidade em busca de tesouros.]=],
		},
		{
			title = "Inimigos por Todos os Lados",
			text = [=[Os {link:forsaken}Renegados{/link} da {link:tarren-mill}Serraria Tarren{/link} querem a coroa, e com ela as cabeças de {link:mug-thol}Mug'thol{/link} e de seus tenentes. Os soldados de {link:southshore}Costa Sul{/link} temem que os ogros desçam ao sopé, e seu marechal paga uma recompensa por cada {link:ogres}ogro{/link} morto. Os ogros também combateram a {link:syndicate}Camarilha{/link} pelas ruínas do reino que ambos reivindicam.]=],
		},
	},
})

Translate("ptBR", "argus-wake", {
	title = "Argus Wake",
	aliases = { "o Argus Wake" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Argus Wake é uma ordem secreta que se fez aliada da {link:syndicate}Camarilha{/link} em {link:alterac-mountains}Alterac{/link}. Seus magos das sombras esperam nas {link:the-uplands}Terras Altas{/link}, e seu hierofante, o {link:orcs}orc{/link} {link:nagaz}Nagaz{/link}, está ao lado do {link:lord-aliden-perenolde}Lorde Aliden Perenolde{/link}. Os nobres de Alterac acreditam ter encontrado amigos poderosos. Estão enganados.]=],
		},
		{
			title = "A Carta",
			text = [=[A verdade veio à luz numa carta encontrada num acampamento da {link:syndicate}Camarilha{/link}. Estava escrita numa cifra tão rara que nem o mestre do saber de {link:southshore}Costa Sul{/link} conseguiu lê-la, e teve de ser levada a um prospector em {link:ironforge}Altaforja{/link}. {link:nagaz}Nagaz{/link} a escrevera ao chefe do Wake, a quem chamava de seu mestre, nomeado por um conselho. A Camarilha, escreveu ele, reconquistaria {link:alterac-mountains}Alterac{/link} com a orientação do Wake, e depois tomaria {link:stromgarde-keep}Stromgarde{/link}. Com uma nação e uma base de poder próprias, o Wake então prepararia o caminho para o que ele chamou de Terceira Hoste. Assinou em nome de {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "O Que Permanece Desconhecido",
			text = [=[O {link:magistrate-henry-maleb}Magistrado Maleb{/link}, de {link:southshore}Costa Sul{/link}, enviou caçadores atrás de {link:nagaz}Nagaz{/link} e de seus magos. Mesmo assim, o magistrado sabe que Nagaz era apenas um servo. Quem lidera o Argus Wake, e até onde vão suas raízes, ninguém em Costa Sul sabe dizer.]=],
		},
	},
})

Translate("ptBR", "stormpike-guard", {
	title = "Guarda de Lançatroz",
	aliases = { "Expedição Lançatroz", "Lançatroz" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Guarda de Lançatroz é uma expedição de {link:dwarves}anões{/link} do clã Lançatroz no {link:alterac-valley}Vale Alterac{/link}, sob o comando do General {link:vanndar-stormpike}Vanndar Stormpike{/link}. De sua fortaleza de Dun Baldar, no norte do vale, vasculham a terra em busca de minério e de relíquias de seu passado. {link:humans}Humanos{/link}, gnomos e elfos noturnos da {link:alliance}Aliança{/link} lutam em suas fileiras.]=],
		},
		{
			title = "O Imperativo",
			text = [=[A expedição se tornou uma guerra. O Rei {link:magni-bronzebeard}Magni Bronzebeard{/link} declarou a tomada dos vales de {link:alterac-mountains}Alterac{/link} um dever do {link:kingdom-of-ironforge}Reino de Altaforja{/link}, e os Lançatroz lutam para reivindicá-los contra os trolls Invernacha e os orcs do {link:frostwolf-clan}Clã Lobo do Gelo{/link}. Os estudiosos da {link:explorers-league}Liga dos Exploradores{/link} marcham com eles, certos de que o vale guarda artefatos que valem a luta. Os orcs os chamam de invasores. Os anões dizem que o vale é deles por direito.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Fora do túnel que leva ao vale, oficiais Lançatroz recebem os soldados da {link:alliance}Aliança{/link}, testam-nos nas cavernas do vale e lhes dão a insígnia da Guarda. Os carneiros dos anões, criados no rancho Ambarmanso em {link:dun-morogh}Dun Morogh{/link}, seguem para o norte para reforçar a expedição.]=],
		},
	},
})

Translate("ptBR", "frostwolf-clan", {
	title = "Clã Lobo do Gelo",
	aliases = { "Lobo do Gelo", "clã Lobo do Gelo", "orcs Lobo do Gelo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O clã Lobo do Gelo é um clã {link:orcs}orc{/link} que faz seu lar no {link:alterac-valley}Vale Alterac{/link}. É o clã do pai de {link:thrall}Thrall{/link}, e o Chefe Guerreiro o tem em alta estima. Seus guerreiros montam os grandes lobos brancos das montanhas, e seu xamã ancião, {link:drek-thar}Drek'Thar{/link}, o lidera da Bastilha Lobo do Gelo, no sul do vale.]=],
		},
		{
			title = "O Exílio",
			text = [=[Em Draenor, os Lobo do Gelo eram um clã orgulhoso sob seu chefe, Durotan. Quando os orcs vieram a {link:azeroth}Azeroth{/link}, Durotan falou contra {link:gul-dan}Gul'dan{/link} e o caminho sombrio que a {link:horde}Horda{/link} havia tomado. Por isso, seu clã foi banido para as {link:alterac-mountains}Montanhas de Alterac{/link}. Durotan e sua companheira mais tarde deixaram o vale, e ambos foram assassinados por agentes de Gul'dan. Seu filho bebê foi encontrado por um oficial humano, que o criou como escravo no {link:durnholde-keep}Forte do Desterro{/link}. Os Lobo do Gelo suportaram o frio e os longos anos sozinhos e, longe da magia vil da Horda, seus xamãs reaprenderam os caminhos dos espíritos.]=],
		},
		{
			title = "O Retorno do Filho",
			text = [=[Anos depois, um jovem {link:orcs}orc{/link} chegou a seu acampamento, fugido do {link:durnholde-keep}Forte do Desterro{/link}. Era o filho de Durotan. {link:drek-thar}Drek'Thar{/link} o ensinou os caminhos do xamã, e do vale {link:thrall}Thrall{/link} partiu para libertar os orcs dos campos e construir uma nova {link:horde}Horda{/link}.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Agora os anões da {link:stormpike-guard}Guarda de Lançatroz{/link} entraram no vale. Os Lobo do Gelo não entregarão seu lar, e a {link:horde}Horda{/link} atendeu a seu chamado.]=],
		},
	},
})
